const event = $json.body ?? $json;
if (event.event !== 'content_approved') throw new Error('Unexpected event type.');
const idea = event.idea ?? {};
if (!event.ownerId || !idea.id || !idea.approvedScript || !idea.approvedScriptHash) throw new Error('Missing owner, idea, approved script or hash.');
const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(idea.approvedScript));
const hash = [...new Uint8Array(digest)].map(x => x.toString(16).padStart(2,'0')).join('');
if (hash !== idea.approvedScriptHash) throw new Error('Approved script hash mismatch.');
if (!Array.isArray(idea.segments) || !idea.segments.length) throw new Error('No video segments received.');
const segments = [...idea.segments].sort((a,b) => a.sequence-b.sequence);
if (segments.some((s,i) => s.sequence !== i+1 || !s.outputStoragePath || !s.narration || !(Number(s.durationSeconds)>0 && Number(s.durationSeconds)<=7.01))) throw new Error('Segment list is missing, unordered or has invalid durations.');
if (event.storage?.bucket !== 'generated-videos' || event.storage?.private !== true || event.storage?.finalPath !== event.ownerId + '/' + idea.id + '/final.mp4') throw new Error('Private storage path validation failed.');
if (event.callback?.url !== 'https://YOUR-VERCEL-DOMAIN.vercel.app/api/video-production/complete') throw new Error('Set the callback URL in the application before activating this workflow.');
return [{ json: { event, scriptHash: hash, segmentCount: segments.length } }];
